<section class="card catering-worksheet"><div class="card-heading"><div><p class="section-kicker">Printable production worksheet</p><h2><?=e($event['title'])?></h2><p><?=e((string)$event['event_date'])?> · <?= (int)$production['guests'] ?> final guests · <?=e((string)$event['fulfillment_method'])?> <?=e((string)$event['fulfillment_window'])?></p></div><span class="badge">Use browser print</span></div><h3>Menu production and labels</h3><?php if($production['items']===[]):?><p>Menu requires team confirmation.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Dish</th><th>Quantity</th><th>Recipe cost</th><th>Dietary/allergen snapshot</th></tr></thead><tbody><?php foreach($production['items'] as $item):?><tr><th scope="row"><?=e((string)$item['name'])?></th><td><?=e((string)($item['quantity']??$production['guests']))?></td><td><?=e($money((int)$item['estimated_cost_minor']))?></td><td><?=e(implode(', ',(array)($item['dietary_tags']??[])))?> / <?=e(implode(', ',(array)($item['allergens']??[])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><h3>Ingredient pull</h3><?php if($production['ingredients']===[]):?><p>No verified recipes are configured. Kitchen quantities require manual confirmation.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Required</th><th>Estimated cost</th><th>Allergens</th></tr></thead><tbody><?php foreach($production['ingredients'] as $ingredient):?><tr><th scope="row"><?=e($ingredient['name'])?></th><td><?=e(number_format((float)$ingredient['quantity'],3).' '.$ingredient['unit'])?></td><td><?=e($money((int)$ingredient['cost_minor']))?></td><td><?=e(implode(', ',json_decode((string)$ingredient['allergens'],true)?:[]))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($production['prep_groups']!==[]):?><h3>Preparation schedule</h3><?php foreach($production['prep_groups'] as $prepDate=>$stations):?><h4><?=e($prepDate)?></h4><?php foreach($stations as $station=>$lines):?><p><strong><?=e($station)?></strong></p><ul><?php foreach($lines as $line):?><li><?=e($line['dish'].' — '.number_format((float)$line['quantity'],3).' '.$line['unit'].' '.$line['ingredient'])?><?= $line['notes']!==''?' · '.e($line['notes']):'' ?><?= $line['label_notes']!==''?' · Label: '.e($line['label_notes']):'' ?></li><?php endforeach;?></ul><?php endforeach;?><?php endforeach;?><?php endif;?><div class="form-grid"><p><strong>Accepted quote revenue</strong><br><?= $production['revenue_minor']===null?'Not available':e($money((int)$production['revenue_minor'])) ?></p><p><strong>Estimated operations cost</strong><br><?=e($money((int)$production['estimated_cost_minor']))?></p><p><strong>Estimated margin</strong><br><?= $production['estimated_margin_minor']===null?'Not available':e($money((int)$production['estimated_margin_minor'])) ?></p><p><strong>Actual cost</strong><br><?= $production['actual_cost_minor']===null?'Incomplete':e($money((int)$production['actual_cost_minor'])) ?></p><p><strong>Actual margin</strong><br><?= $production['actual_margin_minor']===null?'Incomplete':e($money((int)$production['actual_margin_minor'])) ?></p><p><strong>Unreturned equipment exposure</strong><br><?=e($money((int)$production['equipment_exposure_minor']))?></p></div><h3>Delivery manifest</h3><p><?=e(implode(', ',array_filter([(string)$event['venue'],(string)$event['address_line_1'],(string)$event['address_line_2'],(string)$event['city'],(string)$event['region'],(string)$event['postal_code']])))?></p><p><?=nl2br(e((string)$event['setup_instructions']))?></p></section>

